(2366743, 328314, 39144, '<td valign="top">Excellent composition.</td>', 'Excellent composition.', '2006-05-01 01:55:16.000000', NULL, 1),
(2366749, 326222, 39144, '<td valign="top">Never been to London before, but it sure doesn''t seem too packed. Setting that aside, the photo is awesome. It''s funny, generally these indoor shots like this are associated with bad color casts from white balance, so it''s nice to see one that looks a bit more natural and light. Nice work there.</td>', 'Never been to London before, but it sure doesn''t seem too packed. Setting that aside, the photo is awesome. It''s funny, generally these indoor shots like this are associated with bad color casts from white balance, so it''s nice to see one that looks a bit more natural and light. Nice work there.', '2006-05-01 01:57:09.000000', NULL, 1),
(2366752, 328518, 39144, '<td valign="top">Way to catch the emotion involved with his act.</td>', 'Way to catch the emotion involved with his act.', '2006-05-01 01:57:50.000000', NULL, 1),
(2366753, 328041, 39144, '<td valign="top">Excellent composition and exposure. Nice job.</td>', 'Excellent composition and exposure. Nice job.', '2006-05-01 01:58:30.000000', NULL, 1),
(2366762, 327497, 39144, '<td valign="top">You should take advantage of the full 640 pixels. Your photo will always rate higher when you do.</td>', 'You should take advantage of the full 640 pixels. Your photo will always rate higher when you do.', '2006-05-01 02:00:45.000000', NULL, 1),
(2366764, 328111, 39144, '<td valign="top">Way to be in the right place at the right time. Nice work.</td>', 'Way to be in the right place at the right time. Nice work.', '2006-05-01 02:01:41.000000', NULL, 1),
(2366768, 327488, 39144, '<td valign="top">Interesting camera placement. It works well with this photo. And the lighting really invites me in to the photo. Anyone who has been there can relate to this photo.</td>', 'Interesting camera placement. It works well with this photo. And the lighting really invites me in to the photo. Anyone who has been there can relate to this photo.', '2006-05-01 02:02:40.000000', NULL, 1),
(2366776, 328139, 15711, '<td valign="top">NOt photojournalism in the sense I would think but more a fashion photo. Still, well done and she is lovely!!! Nice lighting and the skin and eyes are very pretty.</td>', 'NOt photojournalism in the sense I would think but more a fashion photo. Still, well done and she is lovely!!! Nice lighting and the skin and eyes are very pretty.', '2006-05-01 02:04:14.000000', NULL, 1),
(2366780, 327964, 39144, '<td valign="top">Nice cat photo, but I think it wouldn''ve done better if you could see more of the elderly''s face for this theme.</td>', 'Nice cat photo, but I think it wouldn''ve done better if you could see more of the elderly''s face for this theme.', '2006-05-01 02:05:03.000000', NULL, 1),
