(2366792, 328340, 15711, '<td valign="top">I like this! Cool perspective. Somebody has a great fish eye lens!</td>', 'I like this! Cool perspective. Somebody has a great fish eye lens!', '2006-05-01 02:08:11.000000', NULL, 1),
(2366796, 327910, 15711, '<td valign="top">I thought about going, but drove out to the country instead.  Cute capture.  I''d like to see them a bit less centered. Great colors - love the sky.</td>', 'I thought about going, but drove out to the country instead.  Cute capture.  I''d like to see them a bit less centered. Great colors - love the sky.', '2006-05-01 02:09:53.000000', NULL, 1),
(2366801, 326771, 39144, '<td valign="top">This would do great in a newspaper. Nice work.</td>', 'This would do great in a newspaper. Nice work.', '2006-05-01 02:11:10.000000', NULL, 1),
