(2368047, 326676, 5885, '<td valign="top">Time would run something like this. But, my only beef is - if you are trying to mimick a magazine cover photo, crop it for that format. I''m thinking this image might loose a lot of impact in a vertical crop.</td>', 'Time would run something like this. But, my only beef is - if you are trying to mimick a magazine cover photo, crop it for that format. I''m thinking this image might loose a lot of impact in a vertical crop.', '2006-05-01 11:28:59.000000', NULL, 1),
(2368052, 327963, 5885, '<td valign="top">Nice capture. I can see this with a human interest story.</td>', 'Nice capture. I can see this with a human interest story.', '2006-05-01 11:30:02.000000', NULL, 1),
(2368053, 325864, 33672, '<td valign="top">Great capture in the spirit of the theme.</td>', 'Great capture in the spirit of the theme.', '2006-05-01 11:30:08.000000', NULL, 1),
