(2368062, 327317, 33672, '<td valign="top">Paid him $5 to take the photo? Now that''s helping the local economy! Nice tones and a priceless expression.</td>', 'Paid him $5 to take the photo? Now that''s helping the local economy! Nice tones and a priceless expression.', '2006-05-01 11:31:44.000000', NULL, 1),
(2368063, 328455, 5885, '<td valign="top">This works. I wish you could have gotten a better angle, but this would run, if you had nothing beter.</td>', 'This works. I wish you could have gotten a better angle, but this would run, if you had nothing beter.', '2006-05-01 11:31:56.000000', NULL, 1),
(2368067, 327248, 5885, '<td valign="top">Ahhh, the shots PR departments push on us all the time. The grab and shake. They''re boring, but every photojournalist alive has shot them.</td>', 'Ahhh, the shots PR departments push on us all the time. The grab and shake. They''re boring, but every photojournalist alive has shot them.', '2006-05-01 11:33:08.000000', NULL, 1),
