(2370407, 326086, 20530, '<td valign="top">Eeek, hope I don''t see this in the paper! Must not have been there long, since I can see evidence of blood flow in fingers;) Hope you don''t mind a little razzing; because I really like the image. The lighting, composition and focus are quite nice. Just a little more graphic than I''d expect to see in photojournalism.</td>', 'Eeek, hope I don''t see this in the paper! Must not have been there long, since I can see evidence of blood flow in fingers;) Hope you don''t mind a little razzing; because I really like the image. The lighting, composition and focus are quite nice. Just a little more graphic than I''d expect to see in photojournalism.', '2006-05-01 23:04:18.000000', NULL, 1),
(2370410, 328132, 21816, '<td valign="top">Looks like it could of used a run through Neat Image or something similar as it''s very noisy. It''s a great action shot!</td>', 'Looks like it could of used a run through Neat Image or something similar as it''s very noisy. It''s a great action shot!', '2006-05-01 23:05:57.000000', NULL, 1),
(2370413, 328502, 20530, '<td valign="top">I''m such a sucker for colors like this that I''m not even going to try and figure out how this is photojournalistic. It''s really gorgeous.</td>', 'I''m such a sucker for colors like this that I''m not even going to try and figure out how this is photojournalistic. It''s really gorgeous.', '2006-05-01 23:08:29.000000', NULL, 1),
(2370434, 327998, 20530, '<td valign="top">Superb! Nice motion blur, crisp focus, great colors and crop. Hope it does well.</td>', 'Superb! Nice motion blur, crisp focus, great colors and crop. Hope it does well.', '2006-05-01 23:17:07.000000', NULL, 1),
(2370438, 327445, 51125, '<td valign="top">The glint on the helmet makes this shot.  Plus the look from the man above does not hurt.  Great shot.</td>', 'The glint on the helmet makes this shot.  Plus the look from the man above does not hurt.  Great shot.', '2006-05-01 23:18:30.000000', NULL, 1),
(2370442, 327721, 43774, '<td valign="top">My favourite of the challenge, love the look on the swimmer''s face</td>', 'My favourite of the challenge, love the look on the swimmer''s face', '2006-05-01 23:19:49.000000', NULL, 1),
(2370443, 328507, 20530, '<td valign="top">Nice sentiment, but not really what comes to mind when I think of photojournalism. It''s a bit OOF and the glare is distracting.</td>', 'Nice sentiment, but not really what comes to mind when I think of photojournalism. It''s a bit OOF and the glare is distracting.', '2006-05-01 23:19:58.000000', NULL, 1),
(2370451, 328276, 43774, '<td valign="top">Great set-up, one of my favourites in the challenge (was this taken in Canada? I see French writing on the inside of the gas cover, yet you used American money).</td>', 'Great set-up, one of my favourites in the challenge (was this taken in Canada? I see French writing on the inside of the gas cover, yet you used American money).', '2006-05-01 23:21:26.000000', NULL, 1),
(2370452, 326771, 51125, '<td valign="top">I would have loved to see this from the middel of the road and lower angle</td>', 'I would have loved to see this from the middel of the road and lower angle', '2006-05-01 23:21:44.000000', NULL, 1),
(2370457, 328298, 51125, '<td valign="top">The motion and light are exceptional.</td>', 'The motion and light are exceptional.', '2006-05-01 23:23:42.000000', NULL, 1);
