(2370666, 328478, 51802, '<td valign="top">I don''t see the news story here.  Maybe if your title described a headline.</td>', 'I don''t see the news story here.  Maybe if your title described a headline.', '2006-05-02 00:37:29.000000', NULL, 1),
(2370671, 328282, 51802, '<td valign="top">The processing is a real turn of for me.</td>', 'The processing is a real turn of for me.', '2006-05-02 00:40:02.000000', NULL, 1),
(2370676, 326658, 56047, '<td valign="top">Great expression on his face, and this works real well in B/W, nice tonal range with your conversion. Maybe a wider crop so that his left arm is not cut off.</td>', 'Great expression on his face, and this works real well in B/W, nice tonal range with your conversion. Maybe a wider crop so that his left arm is not cut off.', '2006-05-02 00:42:23.000000', NULL, 1),
(2370687, 327729, 51802, '<td valign="top">How very sad.  Wonderful shot for this challenge!</td>', 'How very sad.  Wonderful shot for this challenge!', '2006-05-02 00:44:49.000000', NULL, 1),
(2370690, 328282, 56047, '<td valign="top">I don''t know if many will like this pic, but I think the vertical lines, grain and B&amp;W really add to the emotional impact of this photo. Great pose - his body language and the distant scoreboard tell the whole story.</td>', 'I don''t know if many will like this pic, but I think the vertical lines, grain and B&W really add to the emotional impact of this photo. Great pose - his body language and the distant scoreboard tell the whole story.', '2006-05-02 00:45:56.000000', NULL, 1),
(2370746, 327729, 51553, '<td valign="top">What the...?!</td>', 'What the...?!', '2006-05-02 01:01:39.000000', NULL, 1),
