(2370781, 326844, 58251, '<td valign="top">Interesting idea.  Perhaps a shot that evokes more of a sense of running?</td>', 'Interesting idea.  Perhaps a shot that evokes more of a sense of running?', '2006-05-02 01:22:23.000000', NULL, 1),
(2370782, 328225, 58251, '<td valign="top">Cool crash, but somebody could take this picture with a cameraphone.</td>', 'Cool crash, but somebody could take this picture with a cameraphone.', '2006-05-02 01:22:52.000000', NULL, 1),
