(2370785, 326206, 58251, '<td valign="top">Just doesn''t scream "Shack resident".  Her story needs to be told through her face.</td>', 'Just doesn''t scream "Shack resident".  Her story needs to be told through her face.', '2006-05-02 01:23:50.000000', NULL, 1),
