(2370877, 327884, 51125, '<td valign="top">I would get right in close on this.  With no people to provide context you need to overwhelm us with the power of the iamges.</td>', 'I would get right in close on this.  With no people to provide context you need to overwhelm us with the power of the iamges.', '2006-05-02 02:20:02.000000', NULL, 1),
(2370880, 328502, 51125, '<td valign="top">Exceptional coloras and nice composition.</td>', 'Exceptional coloras and nice composition.', '2006-05-02 02:21:24.000000', NULL, 1),
(2370887, 328459, 36141, '<td valign="top">Though I''m Dutch, I got married in Rockville MD. 36 years ago, we lived in Bethesda MD for a short while and often ate our dinner in a restaurant in Silver Spring. Your photo brought memories back.<br/>It''s a silence whitness to a horrible event.</td>', 'Though I''m Dutch, I got married in Rockville MD. 36 years ago, we lived in Bethesda MD for a short while and often ate our dinner in a restaurant in Silver Spring. Your photo brought memories back.It''s a silence whitness to a horrible event.', '2006-05-02 02:28:09.000000', NULL, 1),
