(2372703, 327021, 34134, '<td valign="top">Good concept. I like the color, but the artifacts from oversharpening are very distracting.</td>', 'Good concept. I like the color, but the artifacts from oversharpening are very distracting.', '2006-05-02 15:56:25.000000', NULL, 1),
(2372742, 328333, 54399, '<td valign="top">I like this photo, its full of life</td>', 'I like this photo, its full of life', '2006-05-02 16:07:09.000000', NULL, 1),
