(2378950, 326424, 41337, '<td valign="top">Such a great/humorous photo. Maybe a bit of a stretch on the challenge but it''s fine for me.</td>', 'Such a great/humorous photo. Maybe a bit of a stretch on the challenge but it''s fine for me.', '2006-05-03 19:25:22.000000', NULL, 1),
(2378978, 326045, 41337, '<td valign="top">It looks like a strange moment which may be ok for a different purpose but as something for the front page of a newspaper/magazine I just don''t see it. Technically I don''t have any problems with it.</td>', 'It looks like a strange moment which may be ok for a different purpose but as something for the front page of a newspaper/magazine I just don''t see it. Technically I don''t have any problems with it.', '2006-05-03 19:32:20.000000', NULL, 1),
(2378993, 326955, 24642, '<td valign="top">Nice touch.</td>', 'Nice touch.', '2006-05-03 19:36:06.000000', NULL, 1),
(2378996, 328047, 41337, '<td valign="top">Probably more of a two page spread shot and/or inside cover of a magazine? Actually I can see this as a cover shot also. Ok enough of the negatives. I really like this shot. I don''t think I''ve seen a larger reflection captured than this. Amazing. Gets a 9. Good luck.</td>', 'Probably more of a two page spread shot and/or inside cover of a magazine? Actually I can see this as a cover shot also. Ok enough of the negatives. I really like this shot. I don''t think I''ve seen a larger reflection captured than this. Amazing. Gets a 9. Good luck.', '2006-05-03 19:36:24.000000', NULL, 1),
(2379002, 327021, 24642, '<td valign="top">Tells a story and has a strong graphical impact.</td>', 'Tells a story and has a strong graphical impact.', '2006-05-03 19:37:35.000000', NULL, 1),
(2379010, 327534, 41337, '<td valign="top">Not sure if this is front page but I can definitely see this in a magazine perhaps inside cover or for a lead story in one of the pages. Looks great. My only real critique is maybe try a shot closer to one of the poles instead of the middle. The top and bottom poles stand out so much so if you got closer to one of them you''d at least minimize the effect with the other.</td>', 'Not sure if this is front page but I can definitely see this in a magazine perhaps inside cover or for a lead story in one of the pages. Looks great. My only real critique is maybe try a shot closer to one of the poles instead of the middle. The top and bottom poles stand out so much so if you got closer to one of them you''d at least minimize the effect with the other.', '2006-05-03 19:39:00.000000', NULL, 1),
(2379150, 328292, 40101, '<td valign="top">wonderfully creepy.  Not so much the stubble and sneer, but the lack of light in the eyes.</td>', 'wonderfully creepy.  Not so much the stubble and sneer, but the lack of light in the eyes.', '2006-05-03 20:22:34.000000', NULL, 1),
(2379172, 327491, 42005, '<td valign="top">My vote for a ribbon!  Very good shot.</td>', 'My vote for a ribbon!  Very good shot.', '2006-05-03 20:27:23.000000', NULL, 1),
