INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2385013, 328317, 17507, '<td valign="top">great candid - but is it newsworthy? as a photo I like it (especially the guy on the right), but I don''t know what kind of news this would communicate</td>', 'great candid - but is it newsworthy? as a photo I like it (especially the guy on the right), but I don''t know what kind of news this would communicate', '2006-05-05 12:35:04.000000', NULL, 1),
(2385015, 327935, 17507, '<td valign="top">beautiful photograph, but its relationship to the challenge is not at all clear - the only thing carrying it is the title</td>', 'beautiful photograph, but its relationship to the challenge is not at all clear - the only thing carrying it is the title', '2006-05-05 12:35:39.000000', NULL, 1),
(2385017, 326045, 17507, '<td valign="top">good and crisp, nice control of a difficult lighting situation with the white coat right next to the black - bit too much neatimage for me</td>', 'good and crisp, nice control of a difficult lighting situation with the white coat right next to the black - bit too much neatimage for me', '2006-05-05 12:36:23.000000', NULL, 1),
(2385019, 326697, 17507, '<td valign="top">as a lightning photograph, I find this somewhat underwhelming. As a photojournalistic photograph, I don''t understand it to tell any story.</td>', 'as a lightning photograph, I find this somewhat underwhelming. As a photojournalistic photograph, I don''t understand it to tell any story.', '2006-05-05 12:37:02.000000', NULL, 1),
(2385022, 328507, 17507, '<td valign="top">a photograph of a plaque is not very dynamic or creative. the strong yellow cast greatly detracts from whatever interest this photo might otherwise carry</td>', 'a photograph of a plaque is not very dynamic or creative. the strong yellow cast greatly detracts from whatever interest this photo might otherwise carry', '2006-05-05 12:37:41.000000', NULL, 1),
(2385024, 328419, 17507, '<td valign="top">cute!</td>', 'cute!', '2006-05-05 12:37:48.000000', NULL, 1),
(2385234, 327784, 36043, '<td valign="top">Great tonal range at this time of day (sun overhead and bright).  Option: Given she is the focus, I would have prefered not to crop her foot and leave more space in front rather than behind.</td>', 'Great tonal range at this time of day (sun overhead and bright).  Option: Given she is the focus, I would have prefered not to crop her foot and leave more space in front rather than behind.', '2006-05-05 14:33:20.000000', NULL, 1),
(2385245, 327587, 51802, '<td valign="top">WOW!  I''m not sure how else to express how wonderful I think this shot is.</td>', 'WOW!  I''m not sure how else to express how wonderful I think this shot is.', '2006-05-05 14:40:24.000000', NULL, 1),
(2385280, 328407, 50674, '<td valign="top">This reminds me more of a paparazzi shot than real journalism.</td>', 'This reminds me more of a paparazzi shot than real journalism.', '2006-05-05 14:58:45.000000', NULL, 1),
(2385285, 328507, 50674, '<td valign="top">Lighting is not very good, the shot is tilting towards the right side and the photograph would have benefitted from something more in it, not just the sign.</td>', 'Lighting is not very good, the shot is tilting towards the right side and the photograph would have benefitted from something more in it, not just the sign.', '2006-05-05 15:00:31.000000', NULL, 1),
(2385426, 327884, 21430, '<td valign="top">I would have cropped this just a bit tighter to eliminate the post on the left-hand side of the image. It is mildly distracting to the overall image, which would still be just as striking without the left edge, as it is now.</td>', 'I would have cropped this just a bit tighter to eliminate the post on the left-hand side of the image. It is mildly distracting to the overall image, which would still be just as striking without the left edge, as it is now.', '2006-05-05 16:11:07.000000', NULL, 1),
(2385628, 325864, 36043, '<td valign="top">Well done.  Great tonal range and good composition</td>', 'Well done.  Great tonal range and good composition', '2006-05-05 17:37:34.000000', NULL, 1),
(2385631, 328266, 36043, '<td valign="top">Nice composition and simple message.  Could really be a front page pic.</td>', 'Nice composition and simple message.  Could really be a front page pic.', '2006-05-05 17:38:58.000000', NULL, 1),
(2385634, 327664, 36043, '<td valign="top">Great capture of the "moment".  Childs face, note and Mom''s face create a pattern that conveys a message. DOF is right for a newspaper.</td>', 'Great capture of the "moment".  Childs face, note and Mom''s face create a pattern that conveys a message. DOF is right for a newspaper.', '2006-05-05 17:40:37.000000', NULL, 1),
(2385636, 327441, 36043, '<td valign="top">Interesting take.   Not sure the crop would be accepted by an editor.</td>', 'Interesting take.   Not sure the crop would be accepted by an editor.', '2006-05-05 17:41:58.000000', NULL, 1),
(2385639, 327529, 36043, '<td valign="top">Great tonal range.  Clean image.</td>', 'Great tonal range.  Clean image.', '2006-05-05 17:42:34.000000', NULL, 1),
(2385650, 327935, 36043, '<td valign="top">Great color and great tone.  And it made me google the title - can''t ask for much more from a front page photo.</td>', 'Great color and great tone.  And it made me google the title - can''t ask for much more from a front page photo.', '2006-05-05 17:48:49.000000', NULL, 1),
(2385652, 326474, 36043, '<td valign="top">News worthy photo and decent composition.  Maybe a bit tighter crop and a lower angle would add additional impact.</td>', 'News worthy photo and decent composition.  Maybe a bit tighter crop and a lower angle would add additional impact.', '2006-05-05 17:50:17.000000', NULL, 1),
(2385661, 327963, 36043, '<td valign="top">Yes, good title to go with a great moment.   Too bad you couldn''t be a tad lower angle.   Still you did great with this.</td>', 'Yes, good title to go with a great moment.   Too bad you couldn''t be a tad lower angle.   Still you did great with this.', '2006-05-05 17:52:34.000000', NULL, 1),
(2385732, 327706, 3186, '<td valign="top">Good shot</td>', 'Good shot', '2006-05-05 18:22:16.000000', NULL, 1),
(2385812, 328507, 37719, '<td valign="top">I would like this better if it was sharper.  The brass plaque has nice sharp edges with the raised letters and that just doesn''t translate in this shot.</td>', 'I would like this better if it was sharper.  The brass plaque has nice sharp edges with the raised letters and that just doesn''t translate in this shot.', '2006-05-05 18:58:50.000000', NULL, 1),
(2385814, 327352, 19040, '<td valign="top">I like the effects of the smoke, hazy and almost surreal.</td>', 'I like the effects of the smoke, hazy and almost surreal.', '2006-05-05 18:59:10.000000', NULL, 1),
(2385817, 328274, 19040, '<td valign="top">Cute photo. The grainy effects add to it. The same with it being in black and white.</td>', 'Cute photo. The grainy effects add to it. The same with it being in black and white.', '2006-05-05 19:01:18.000000', NULL, 1),
(2385818, 328041, 19040, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2006-05-05 19:02:02.000000', NULL, 1),
(2385821, 328409, 19040, '<td valign="top">I really like what you did here.</td>', 'I really like what you did here.', '2006-05-05 19:05:04.000000', NULL, 1),
(2385831, 326474, 19040, '<td valign="top">Wow, how lucky for you to have your camera.</td>', 'Wow, how lucky for you to have your camera.', '2006-05-05 19:12:48.000000', NULL, 1),
(2385858, 328225, 47852, '<td valign="top">Good capture of the scene right after it happened.  Looks like the lighting was a bit flat which left the colors a bit dull.  Would black and white work better here?</td>', 'Good capture of the scene right after it happened.  Looks like the lighting was a bit flat which left the colors a bit dull.  Would black and white work better here?', '2006-05-05 19:28:02.000000', NULL, 1),
(2385861, 327697, 47852, '<td valign="top">Can definately see this one as a photo to accompany an article.  I think I might like to see the main subject a bit off of center.</td>', 'Can definately see this one as a photo to accompany an article.  I think I might like to see the main subject a bit off of center.', '2006-05-05 19:29:21.000000', NULL, 1),
(2385867, 327963, 47852, '<td valign="top">Great shot that tells just a portion of a story.  Your eye goes between the man sitting and the child who is turned around, but I think the child''s clothing and shoes are just a bit too bright.  Well captured!</td>', 'Great shot that tells just a portion of a story.  Your eye goes between the man sitting and the child who is turned around, but I think the child''s clothing and shoes are just a bit too bright.  Well captured!', '2006-05-05 19:31:34.000000', NULL, 1),
(2385872, 328497, 47852, '<td valign="top">You''ve definately captured all of the parts of your headline.. the protest, the place.. but I feel like there is a bit of emotion missing.  Perhaps a closer shot of one persons expression or a more clearly defined focal point would help?</td>', 'You''ve definately captured all of the parts of your headline.. the protest, the place.. but I feel like there is a bit of emotion missing.  Perhaps a closer shot of one persons expression or a more clearly defined focal point would help?', '2006-05-05 19:33:54.000000', NULL, 1),
(2385878, 328035, 47852, '<td valign="top">The shot definately fits the headline you''ve given, but the shot alone wouldn''t be enough to draw me in to read the article.  Perhaps adding a person to the shot to show how they''re feeling about the theft would be more effective?</td>', 'The shot definately fits the headline you''ve given, but the shot alone wouldn''t be enough to draw me in to read the article.  Perhaps adding a person to the shot to show how they''re feeling about the theft would be more effective?', '2006-05-05 19:36:54.000000', NULL, 1),
(2385883, 327738, 47852, '<td valign="top">Neat shot that would definately pull me in to read a little bit more about it.  I''m not sure if I can picture a shot like this in the newspaper with so much negative space and nothing to frame the bottom or give a sense of scale.</td>', 'Neat shot that would definately pull me in to read a little bit more about it.  I''m not sure if I can picture a shot like this in the newspaper with so much negative space and nothing to frame the bottom or give a sense of scale.', '2006-05-05 19:40:23.000000', NULL, 1),
(2385885, 327443, 47852, '<td valign="top">A neat shot, but I''m not sure that I can picture the accompanying article.</td>', 'A neat shot, but I''m not sure that I can picture the accompanying article.', '2006-05-05 19:42:11.000000', NULL, 1),
(2385889, 327963, 2158, '<td valign="top">This sure tells a story.  Especially with the small child staring at him.  So sad.</td>', 'This sure tells a story.  Especially with the small child staring at him.  So sad.', '2006-05-05 19:44:35.000000', NULL, 1),
(2386017, 327998, 3032, '<td valign="top">Good frame filling shot, sharp with panning motion blur. Good.</td>', 'Good frame filling shot, sharp with panning motion blur. Good.', '2006-05-05 20:56:56.000000', NULL, 1),
(2386130, 327399, 48228, '<td valign="top">"WOW", I love this as you have taken it at a great angle.....</td>', '"WOW", I love this as you have taken it at a great angle.....', '2006-05-05 21:55:16.000000', NULL, 1),
(2386135, 327664, 48228, '<td valign="top">So cute.....</td>', 'So cute.....', '2006-05-05 21:59:09.000000', NULL, 1),
(2386139, 325627, 48228, '<td valign="top">This is a winner in my book and yes a "10" from me, as it is one of the best re suiting the challenge.....</td>', 'This is a winner in my book and yes a "10" from me, as it is one of the best re suiting the challenge.....', '2006-05-05 22:01:51.000000', NULL, 1),
(2386146, 328502, 48228, '<td valign="top">Cool colors.....</td>', 'Cool colors.....', '2006-05-05 22:03:30.000000', NULL, 1),
(2386149, 325938, 48228, '<td valign="top">This is good, well done.....</td>', 'This is good, well done.....', '2006-05-05 22:04:08.000000', NULL, 1),
(2386152, 328476, 48228, '<td valign="top">Good shot.....</td>', 'Good shot.....', '2006-05-05 22:05:25.000000', NULL, 1),
