(2393169, 328458, 24454, '<td valign="top">I had a feeling this one was yours.  I loved it!   I actually was the one who gave you your 1 10 because I loved the motion, the happy look on the dancer''s face.  I thought it was great.</td>', 'I had a feeling this one was yours.  I loved it!   I actually was the one who gave you your 1 10 because I loved the motion, the happy look on the dancer''s face.  I thought it was great.', '2006-05-08 12:25:17.000000', NULL, 0),
(2393192, 327412, 11854, '<td valign="top">Congrats on your ribbon! My cousin competed in this (3rd place high school girls). She had a blast. You really captured the excitement. Great shot!</td>', 'Congrats on your ribbon! My cousin competed in this (3rd place high school girls). She had a blast. You really captured the excitement. Great shot!', '2006-05-08 12:30:28.000000', NULL, 0),
