(2393225, 328119, 28299, '<td valign="top">Powerful Brando! Great capture.</td>', 'Powerful Brando! Great capture.', '2006-05-08 12:45:15.000000', NULL, 0),
(2393249, 327721, 36060, '<td valign="top">Congrats on your blue, great capture!</td>', 'Congrats on your blue, great capture!', '2006-05-08 12:55:10.000000', NULL, 0),
(2393252, 325938, 24454, '<td valign="top">This was one of my favorites in this challenge!  I am so happy it scored so high.   I would have liked to see this one in the top 10 (or ribbon)!    Fantastic job!</td>', 'This was one of my favorites in this challenge!  I am so happy it scored so high.   I would have liked to see this one in the top 10 (or ribbon)!    Fantastic job!', '2006-05-08 12:55:44.000000', NULL, 0),
(2393261, 326676, 24454, '<td valign="top">I LOVED this photo!!   You did an excellent job shooting it and processing it!  Congratulations on a top 10 placing.  It sooo deserved it!!!<br/> <br/></td>', 'I LOVED this photo!!   You did an excellent job shooting it and processing it!  Congratulations on a top 10 placing.  It sooo deserved it!!! ', '2006-05-08 12:58:09.000000', NULL, 0),
(2393262, 326278, 53147, '<td valign="top">Trading Post -<br/>Right off the bat - way too much shadow for me and not enough detail. The light in the back, while it does shine on the wall, just seems so bright that that is where my eyes go to and it just doesnt offer anything but being a bright spot. I gave this a 4 overall. I understand the idea and felt it made the challenge description, but technically it is too dark for me without enough detailed highlights. And from that the interest/appeal level was diminished.</td>', 'Trading Post -Right off the bat - way too much shadow for me and not enough detail. The light in the back, while it does shine on the wall, just seems so bright that that is where my eyes go to and it just doesnt offer anything but being a bright spot. I gave this a 4 overall. I understand the idea and felt it made the challenge description, but technically it is too dark for me without enough detailed highlights. And from that the interest/appeal level was diminished.', '2006-05-08 12:58:35.000000', NULL, 0),
(2393265, 327998, 36060, '<td valign="top">Congrats on your ribbon!</td>', 'Congrats on your ribbon!', '2006-05-08 12:59:19.000000', NULL, 0),
