INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2393275, 327963, 36060, '<td valign="top">Congratulations on your top five finish.</td>', 'Congratulations on your top five finish.', '2006-05-08 13:01:59.000000', NULL, 0),
(2393277, 328409, 24454, '<td valign="top">Courtenay this is AWESOME!  I gave it on of your 4 10''s!   Such a perfect capture with the little catcher looking up expectantly at the umpire with all the dust flying everywhere.   I love it!!!   Just added it to my favorites so I can see it often :)<br/> <br/></td>', 'Courtenay this is AWESOME!  I gave it on of your 4 10''s!   Such a perfect capture with the little catcher looking up expectantly at the umpire with all the dust flying everywhere.   I love it!!!   Just added it to my favorites so I can see it often :) ', '2006-05-08 13:03:02.000000', NULL, 0),
(2393279, 327352, 24454, '<td valign="top">David, this is really an awesome photojournalistic photo!  You can feel the energy of the scene.  Fantastic capture!!   I would have liked to see this one score much higher!</td>', 'David, this is really an awesome photojournalistic photo!  You can feel the energy of the scene.  Fantastic capture!!   I would have liked to see this one score much higher!', '2006-05-08 13:04:31.000000', NULL, 0),
(2393281, 327640, 36060, '<td valign="top">Congratulations on your top 10 finish. Well done!</td>', 'Congratulations on your top 10 finish. Well done!', '2006-05-08 13:04:58.000000', NULL, 0),
(2393282, 326676, 36060, '<td valign="top">Congratulations on your top 10 finish!</td>', 'Congratulations on your top 10 finish!', '2006-05-08 13:05:26.000000', NULL, 0),
(2393284, 327491, 36060, '<td valign="top">Congratulations on your top 10 finish.</td>', 'Congratulations on your top 10 finish.', '2006-05-08 13:05:47.000000', NULL, 0),
(2393285, 325627, 36060, '<td valign="top">Congratulations on your top 10 finish. Very good shot!</td>', 'Congratulations on your top 10 finish. Very good shot!', '2006-05-08 13:06:15.000000', NULL, 0),
(2393286, 326474, 36060, '<td valign="top">Congratulations on your top 10 finish.</td>', 'Congratulations on your top 10 finish.', '2006-05-08 13:06:36.000000', NULL, 0),
(2393323, 328416, 53147, '<td valign="top">Trading Post -<br/>As a performer who plays with fire as well, I enjoyed this shot. Good colors (maybe saturated just a tad bit more) and the flame looks great. You caught a moment in a performance that is alot of fun. His face seems a bit washed out. And the background image on the canvas is a bit of a distraction. At first I thought hew was wearing a hat or had weird hairdo. A vertical shot may have been nice as his outfit probably looked pretty cool. That would have garnered the pic more interest I think. Overall a fun shot. I gave this a 6.</td>', 'Trading Post -As a performer who plays with fire as well, I enjoyed this shot. Good colors (maybe saturated just a tad bit more) and the flame looks great. You caught a moment in a performance that is alot of fun. His face seems a bit washed out. And the background image on the canvas is a bit of a distraction. At first I thought hew was wearing a hat or had weird hairdo. A vertical shot may have been nice as his outfit probably looked pretty cool. That would have garnered the pic more interest I think. Overall a fun shot. I gave this a 6.', '2006-05-08 13:16:20.000000', NULL, 0),
(2393336, 327412, 5885, '<td valign="top">Really good work Eug. This is one of my absolute favorites in the challenge. Very well done shot. Ofcourse I showed you earlier the one little flaw I saw with it, but congrats on a ribbon on a very deserving photo.</td>', 'Really good work Eug. This is one of my absolute favorites in the challenge. Very well done shot. Ofcourse I showed you earlier the one little flaw I saw with it, but congrats on a ribbon on a very deserving photo.', '2006-05-08 13:19:50.000000', NULL, 0),
(2393341, 327721, 5885, '<td valign="top">This was a really well done shot and I knew it was a contender for the ribbon. Such good use of framing to capture a facial expression that scream dedication. Great work and well deserved ribbon.</td>', 'This was a really well done shot and I knew it was a contender for the ribbon. Such good use of framing to capture a facial expression that scream dedication. Great work and well deserved ribbon.', '2006-05-08 13:21:19.000000', NULL, 0),
(2393350, 327998, 5885, '<td valign="top">Your first attempt at motorbike photography? OMG, I can''t wait to see the other attempts. Great work! Congrats with your ribbon on one of my top picks.</td>', 'Your first attempt at motorbike photography? OMG, I can''t wait to see the other attempts. Great work! Congrats with your ribbon on one of my top picks.', '2006-05-08 13:22:41.000000', NULL, 0),
(2393395, 328213, 53147, '<td valign="top">Trading post -<br/>This shot didnt work so well for me. Looking at it closer now there seems to be an shadow(?) on the front of the car and tire. Not sure hwat would cause that. Cropping to have the whole wheel in the shot may have helped the shot not feel so cramped in the front. The background of the image doesnt hold much ineterest for me personally. A clear sky with some steam/smoke coming out of the stack would have been nice. Something a bit more. The lighting and contrast also seem a bit bright overall. Without the title I probably would not have had any idea what the pic was trying to say. Hope this isn''t too harsh. Just my lwoly opinion for whatever it is worth.</td>', 'Trading post -This shot didnt work so well for me. Looking at it closer now there seems to be an shadow(?) on the front of the car and tire. Not sure hwat would cause that. Cropping to have the whole wheel in the shot may have helped the shot not feel so cramped in the front. The background of the image doesnt hold much ineterest for me personally. A clear sky with some steam/smoke coming out of the stack would have been nice. Something a bit more. The lighting and contrast also seem a bit bright overall. Without the title I probably would not have had any idea what the pic was trying to say. Hope this isn''t too harsh. Just my lwoly opinion for whatever it is worth.', '2006-05-08 13:33:23.000000', NULL, 0),
(2393415, 328403, 53147, '<td valign="top">Trading Post - <br/>I gave this one a 4 (sorry Deb). I think a slightly wider crop to show off mor eof the vendors stuff may have helped. Also maybe a different angle to see more of the mom and kids face as they are eyeballing the stuff. Depth of focus works well. Colors could have been brought out just a tad bit more for further separation. Overall interest/appeal was kind of low for me since I was not really able to connect to the principles in the pic. Just didnt tell me a story overall.</td>', 'Trading Post - I gave this one a 4 (sorry Deb). I think a slightly wider crop to show off mor eof the vendors stuff may have helped. Also maybe a different angle to see more of the mom and kids face as they are eyeballing the stuff. Depth of focus works well. Colors could have been brought out just a tad bit more for further separation. Overall interest/appeal was kind of low for me since I was not really able to connect to the principles in the pic. Just didnt tell me a story overall.', '2006-05-08 13:38:02.000000', NULL, 0),
